const input=$json.body??$json;
const s=v=>String(v??"").trim();
const status=s(input.status??input.delivery_status??input.provider_receipt?.status).toLowerCase();
const event=s(input.event_type??input.outcome??input.provider_receipt?.event_type).toLowerCase();
const channel=s(input.channel??input.message?.channel).toLowerCase()||"sms";
const dnc=input.dnc===true||input.dnc_suppressed===true||event==="opt_out"||status==="dnc";
const sellerReply=s(input.seller_reply??input.inbound_message??input.message_text);
const providerMessageId=s(input.provider_message_id??input.provider_receipt?.provider_message_id);
const requestId=s(input.request_id??input.message?.request_id);
const auditId=s(input.audit_id);
const leadId=s(input.lead_id??input.identity?.lead_id), dealId=s(input.deal_id??input.identity?.deal_id), threadId=s(input.thread_id??input.identity?.thread_id);
const missing=[]; if(!leadId&&!dealId)missing.push("lead_id_or_deal_id"); if(!threadId)missing.push("thread_id"); if(!requestId)missing.push("request_id");
let action="monitor", nextWorkflow="wf-099-seller-follow-up-timing-cadence", dispatchMode="internal_follow_up_queue", reason="re-engagement outcome recorded; continue monitoring", priority="normal";
if(dnc){action="suppress";nextWorkflow=null;dispatchMode="blocked";reason="DNC/opt-out detected; suppress future autonomous outreach";priority="critical";}
else if(sellerReply||event==="seller_reply"||event==="inbound_reply"){action="analyze_seller_reply";nextWorkflow="wf-097-ai-seller-response-intelligence";dispatchMode="internal_ai_analysis";reason="seller replied to re-engagement; return to conversation intelligence before responding";priority="high";}
else if(status==="failed"||status==="error"||status==="timeout"||status==="transport_error"){action="reconcile_delivery";nextWorkflow="wf-089-communication-reconciliation";dispatchMode="internal_reconciliation";reason="re-engagement delivery failed or timed out";priority="high";}
else if(status==="sent"||status==="delivered"||event==="outbound_sent"||event==="outbound_delivered"){action="wait_for_response";nextWorkflow="wf-099-seller-follow-up-timing-cadence";dispatchMode="internal_follow_up_queue";reason="re-engagement delivered; do not send another message immediately";}
else {action="human_review";nextWorkflow="wf-078-seller-conversation-response-intelligence";dispatchMode="human_review";reason="outcome is not sufficiently classified for autonomous action";priority="normal";}
const actionId="seller-reengagement-outcome:"+((threadId||leadId||dealId||"unknown"))+":"+(requestId||auditId||"event")+":v1";
return[{json:{ok:missing.length===0,action:{action_id:actionId,next_action:action,status:status||event||"unknown",reason,priority,deterministic:true},identity:{lead_id:leadId||null,deal_id:dealId||null,thread_id:threadId||null},communication:{channel,request_id:requestId||null,provider_message_id:providerMessageId||null,audit_id:auditId||null,seller_reply_present:Boolean(sellerReply),dnc},routing:{next_workflow:nextWorkflow,dispatch_mode:dispatchMode},missing_requirements:missing}}];
